// TestEndToEndPoseidon2 compiles a circuit with gkrapi, then proves and verifies it with Poseidon2,
// the proof being rebuilt by DeserializeProof from the elements of its Flatten, and checks that
// tampering with the proof is rejected.
func TestEndToEndPoseidon2(t *testing.T) {
	const nbInstances = 16

	api := gkrapi.New()
	x := api.NewInput()
	y := api.NewInput()
	api.Export(api.Gate(gkrtesting.ConstantPositionsGate, x, y))
	circuit, schedule, err := api.Compile(gkr.MamaBearE3(), gkrapi.ConsolidateAll)
	require.NoError(t, err)

	assignment := make(WireAssignment, len(circuit))
	for _, w := range []gkr.Variable{x, y} {
		assignment[w] = make([]mamabear.Element, nbInstances)
		mamabear.Vector(assignment[w]).MustSetRandom()
	}
	// The output column is left nil: Prove computes it.

	proof, proverClaims, err := Prove(circuit, schedule, assignment, newPoseidon2Hasher())
	require.NoError(t, err)

	var flattened []extensions.E3
	for _, element := range proof.Flatten() {
		flattened = append(flattened, *element)
	}

	verify := func(serialized []extensions.E3) (Claims, error) {
		deserialized, err := DeserializeProof(circuit, schedule, serialized)
		if err != nil {
			return nil, err
		}
		claims, err := Verify(circuit, schedule, assignment.NumVars(), deserialized, newPoseidon2Hasher())
		if err != nil {
			return nil, err
		}
		return claims, claims.Check(assignment)
	}

	verifierClaims, err := verify(flattened)
	require.NoError(t, err)
	assert.Equal(t, proverClaims, verifierClaims)

	outsideBaseField := false
	for _, wireClaims := range verifierClaims {
		for _, claim := range wireClaims {
			outsideBaseField = outsideBaseField || claim.Evaluation.BigInt(nil) == nil
		}
	}
	assert.True(t, outsideBaseField, "no claim is outside the base field: the challenges are not extension elements")

	tampered := slices.Clone(flattened)
	tampered[0].Add(&tampered[0], &oneExt)
	_, err = verify(tampered)
	assert.Error(t, err, "tampered proof accepted")
}

// TestCheckRejectsMismatchedLengths checks that Claims.Check rejects assignments of another size
// than the claims', and ones missing a claimed wire.
func TestCheckRejectsMismatchedLengths(t *testing.T) {
	api := gkrapi.New()
	x := api.NewInput()
	y := api.NewInput()
	z := api.Mul(x, y)
	circuit, schedule, err := api.Compile(gkr.MamaBearE3(), gkrapi.ConsolidateAll)
	require.NoError(t, err)

	elements := func(values ...uint64) []mamabear.Element {
		res := make([]mamabear.Element, len(values))
		for i, v := range values {
			res[i] = mamabear.NewElement(v)
		}
		return res
	}

	// The prover proves instances 0 and 2 of the larger assignment below only.
	proven := make(WireAssignment, len(circuit))
	proven[x], proven[y] = elements(2, 4), elements(5, 6)
	proof, _, err := Prove(circuit, schedule, proven, newMessageCounter(1, 1))
	require.NoError(t, err)

	claims, err := Verify(circuit, schedule, 1, proof, newMessageCounter(1, 1))
	require.NoError(t, err)
	assert.NoError(t, claims.Check(proven))

	// Instances 1 and 3 of z are false.
	larger := make(WireAssignment, len(circuit))
	larger[x], larger[y], larger[z] = elements(2, 3, 4, 5), elements(5, 7, 6, 8), elements(10, 999, 24, 12345)
	assert.Error(t, claims.Check(larger), "claims about 2 instances accepted against an assignment of 4")

	inputsOnly := make(WireAssignment, len(circuit))
	inputsOnly[x], inputsOnly[y] = elements(2, 4), elements(5, 6)
	assert.NotPanics(t, func() {
		assert.Error(t, claims.Check(inputsOnly), "claims on a wire accepted without an assignment")
	})
}

// proveAndVerify proves assignment against schedule and verifies the proof rebuilt by
// DeserializeProof from the elements of its Flatten, then asserts that: every wire of
// schedule[0] has exactly one claim, and all of them share one point; the number of
// elements in the proof, counted with proof.Flatten(), equals c.ProofSize(schedule, logNbInstances);
// tampering instance 0 of any wire with claims makes Check fail; a bad hash makes Verify or Check
// fail; and tampering the first element of any finalEvalProof or partial sum polynomial in the
// proof, the output entry included, makes Verify reject it — except for the claimed evaluation of
// an output wire that is a circuit input outside schedule[0], which nothing in the proof cross-checks:
// there Verify must accept, and only Claims.Check catches the tampering.
func proveAndVerify(t *testing.T, c Circuit, schedule constraint.GkrProvingSchedule, assignment WireAssignment) {
	t.Helper()
	proof, proverClaims, err := Prove(c, schedule, assignment, newMessageCounter(1, 1))
	assert.NoError(t, err)
	assert.NoError(t, proverClaims.Check(assignment))

	var flattened []extensions.E3
	for _, element := range proof.Flatten() {
		flattened = append(flattened, *element)
	}
	deserialized, err := DeserializeProof(c, schedule, flattened)
	assert.NoError(t, err)

	logNbInstances := assignment.NumVars()
	verifierClaims, err := Verify(c, schedule, logNbInstances, deserialized, newMessageCounter(1, 1))
	assert.NoError(t, err, "proof rejected")
	assert.Equal(t, proverClaims, verifierClaims)
	assert.NoError(t, verifierClaims.Check(assignment))

	consolidated := c.LevelWires(schedule[0])
	var consolidationPoint []extensions.E3
	for wI, isConsolidated := range consolidated {
		if !isConsolidated {
			continue
		}
		if assert.Len(t, verifierClaims[wI], 1, "wire %d: expected exactly one claim", wI) {
			if consolidationPoint == nil {
				consolidationPoint = verifierClaims[wI][0].EvaluationPoint
			} else {
				assert.Equal(t, consolidationPoint, verifierClaims[wI][0].EvaluationPoint, "wire %d: expected the shared consolidation point", wI)
			}
		}
	}

	var nbProofElems int
	for range proof.Flatten() {
		nbProofElems++
	}
	assert.Equal(t, c.ProofSize(schedule, logNbInstances), nbProofElems)

	for wI := range verifierClaims {
		assignment[wI][0].Add(&assignment[wI][0], &one)
		assert.NotNil(t, verifierClaims.Check(assignment), "wire %d: tampered assignment accepted", wI)
		assignment[wI][0].Sub(&assignment[wI][0], &one)
	}

	badHashClaims, err := Verify(c, schedule, logNbInstances, proof, newMessageCounter(0, 1))
	if err == nil {
		err = badHashClaims.Check(assignment)
	}
	assert.NotNil(t, err, "bad proof accepted")

	for levelI := range proof {
		tamperTargets := [][]extensions.E3{proof[levelI].finalEvalProof}
		for _, p := range proof[levelI].partialSumPolys {
			tamperTargets = append(tamperTargets, p)
		}
		for _, target := range tamperTargets {
			if len(target) == 0 {
				continue
			}
			target[0].Add(&target[0], &oneExt)
			claims, err := Verify(c, schedule, logNbInstances, proof, newMessageCounter(1, 1))
			if levelI < len(schedule) || !c.IsInput(c.Outputs()[0]) || consolidated[c.Outputs()[0]] {
				assert.Error(t, err, "tampered proof accepted at level %d", levelI)
			} else {
				assert.NoError(t, err, "level %d: Verify should accept a tampered claim it cannot cross-check", levelI)
				assert.Error(t, claims.Check(assignment), "level %d: tampered output claim accepted", levelI)
			}
			target[0].Sub(&target[0], &oneExt)
		}
	}
}

