func unmarshalProof(printable gkrtesting.PrintableProof) (Proof, error) {
	proof := make(Proof, len(printable))
	for i := range printable {
		finalEvalProof := []extensions.E3(nil)

		if printable[i].FinalEvalProof != nil {
			finalEvalSlice := reflect.ValueOf(printable[i].FinalEvalProof)
			finalEvalProof = make([]extensions.E3, finalEvalSlice.Len())
			for k := range finalEvalProof {
				if err := gkrtesting.SetElement(&finalEvalProof[k], finalEvalSlice.Index(k).Interface()); err != nil {
					return nil, err
				}
			}
		}

		proof[i] = sumcheckProof{
			partialSumPolys: make([]polynomial.PolynomialE3, len(printable[i].PartialSumPolys)),
			finalEvalProof:  finalEvalProof,
		}
		for k := range printable[i].PartialSumPolys {
			var err error
			if proof[i].partialSumPolys[k], err = gkrtesting.SliceToElementSlice[extensions.E3](printable[i].PartialSumPolys[k]); err != nil {
				return nil, err
			}
		}
	}
	return proof, nil
}

type TestCase struct {
	Circuit         gkr.SerializableCircuit
	Hash            fieldHasher
	Proof           Proof
	FullAssignment  WireAssignment
	InOutAssignment WireAssignment
	Schedule        constraint.GkrProvingSchedule
}

var testCases = make(map[string]*TestCase)

func newTestCase(path string) (*TestCase, error) {
	path, err := filepath.Abs(path)
	if err != nil {
		return nil, err
	}
	dir := filepath.Dir(path)

	tCase, ok := testCases[path]
	if ok {
		return tCase, nil
	}

	info, err := cache.ReadTestCaseInfo(path)
	if err != nil {
		return nil, err
	}

	circuit, _ := cache.GetCircuit(filepath.Join(dir, info.Circuit))
	var _hash fieldHasher
	if _hash, err = hashFromDescription(info.Hash); err != nil {
		return nil, err
	}
	var proof Proof
	if proof, err = unmarshalProof(info.Proof); err != nil {
		return nil, err
	}
	var schedule constraint.GkrProvingSchedule
	if schedule, err = info.Schedule.ToProvingSchedule(); err != nil {
		return nil, err
	}
	if schedule == nil {
		if schedule, err = gkrcore.DefaultProvingSchedule(circuit, gkrcore.SNARKConsolidationMode); err != nil {
			return nil, err
		}
	}

	outputSet := make(map[int]bool, len(circuit))
	for _, o := range circuit.Outputs() {
		outputSet[o] = true
	}

	fullAssignment := make(WireAssignment, len(circuit))
	inOutAssignment := make(WireAssignment, len(circuit))

	inI, outI := 0, 0
	for i := range circuit {
		var assignmentRaw []interface{}
		if circuit[i].IsInput() {
			if inI == len(info.Input) {
				return nil, fmt.Errorf("fewer input in vector than in circuit")
			}
			assignmentRaw = info.Input[inI]
			inI++
		} else if outputSet[i] {
			if outI == len(info.Output) {
				return nil, fmt.Errorf("fewer output in vector than in circuit")
			}
			assignmentRaw = info.Output[outI]
			outI++
		}
		if assignmentRaw != nil {
			var wireAssignment []mamabear.Element
			if wireAssignment, err = gkrtesting.SliceToElementSlice[mamabear.Element](assignmentRaw); err != nil {
				return nil, err
			}

			fullAssignment[i] = wireAssignment
			inOutAssignment[i] = wireAssignment
		}
	}

	fullAssignment.Complete(circuit)

	for i := range circuit {
		if outputSet[i] {
			if err = gkrtesting.SliceEquals(inOutAssignment[i], fullAssignment[i]); err != nil {
				return nil, fmt.Errorf("assignment mismatch: %v", err)
			}
		}
	}

	tCase = &TestCase{
		FullAssignment:  fullAssignment,
		InOutAssignment: inOutAssignment,
		Proof:           proof,
		Hash:            _hash,
		Circuit:         circuit,
		Schedule:        schedule,
	}

	testCases[path] = tCase

	return tCase, nil
}
